
local ws=game:GetService("Workspace")
local pl=ws:FindFirstChild("NovaMCP")
local core=pl:FindFirstChild("CommandHandlers"):FindFirstChild("Core")

-- SelectionHandlers
local sh=core:FindFirstChild("SelectionHandlers")
sh.Source="--[[ NovaMCP SelectionHandlers ]]\nlocal PathResolver = require(script.Parent.Parent.Parent.Utils.PathResolver)\nlocal InstanceIdentity = require(script.Parent.Parent.Parent.Utils.InstanceIdentity)\nlocal SelectionMonitor = require(script.Parent.Parent.Parent.SelectionMonitor)\nlocal Selection = game:GetService('Selection')\nlocal module = {}\nfunction module.get_selection(params)\n local ok, result = pcall(function()\n  local sel = Selection:Get()\n  local items = {}\n  for _, inst in ipairs(sel) do\n   local path = PathResolver.getPath(inst)\n   if PathResolver.isPathAllowed(path) then\n    table.insert(items, InstanceIdentity.attach({path=path}, inst))\n   else\n    table.insert(items, {name=inst.Name, className=inst.ClassName, path='[FORBIDDEN]'})\n   end\n  end\n  return {selection=items, count=#items}\n end)\n if ok then return {success=true, data=result} else return {success=false, error=tostring(result)} end\nend\nfunction module.set_selection(params)\n local ok, result = pcall(function()\n  local paths = params.paths\n  if not paths or type(paths)~='table' then error('paths parameter must be an array') end\n  local instances = {}; local resolved = {}\n  for _, p in ipairs(paths) do\n   local inst = PathResolver.resolve(p)\n   if inst then table.insert(instances, inst); table.insert(resolved, PathResolver.getPath(inst))\n   else warn('[SelectionHandlers] Failed to resolve path:', p) end\n  end\n  Selection:Set(instances)\n  return {selected=#instances, paths=resolved, count=#instances}\n end)\n if ok then return {success=true, data=result} else return {success=false, error=tostring(result)} end\nend\nfunction module.clear_selection(params)\n local ok, err = pcall(function() Selection:Set({}) end)\n if ok then return {success=true, data={}} else return {success=false, error=tostring(err)} end\nend\nfunction module.get_cached_selection(params)\n return SelectionMonitor.getCachedSelection(params.maxAge)\nend\nreturn module"

-- TagHandlers
local th=core:FindFirstChild("TagHandlers")
th.Source="--[[ NovaMCP TagHandlers ]]\nlocal CollectionService = game:GetService('CollectionService')\nlocal PathResolver = require(script.Parent.Parent.Parent.Utils.PathResolver)\nlocal Serializer = require(script.Parent.Parent.Parent.Utils.Serializer)\nlocal module = {}\nfunction module.add_tag(params)\n local path = params.path; local tag = params.tag\n if not path or path=='' then return {success=false, error='path is required'} end\n if not tag or tag=='' then return {success=false, error='tag is required'} end\n if not PathResolver.isPathAllowed(path) then return {success=false, error='Forbidden path: '..path} end\n local inst = PathResolver.resolve(path)\n if not inst then return {success=false, error='Instance not found: '..path} end\n local ok, err = pcall(function() CollectionService:AddTag(inst, tag) end)\n if not ok then return {success=false, error=string.format(\"Failed to add tag '%s': %s\", tag, tostring(err))} end\n return {success=true, data={path=path, tag=tag, added=true}}\nend\nfunction module.remove_tag(params)\n local path = params.path; local tag = params.tag\n if not path or path=='' then return {success=false, error='path is required'} end\n if not tag or tag=='' then return {success=false, error='tag is required'} end\n if not PathResolver.isPathAllowed(path) then return {success=false, error='Forbidden path: '..path} end\n local inst = PathResolver.resolve(path)\n if not inst then return {success=false, error='Instance not found: '..path} end\n local existed = CollectionService:HasTag(inst, tag)\n local ok, err = pcall(function() CollectionService:RemoveTag(inst, tag) end)\n if not ok then return {success=false, error=string.format(\"Failed to remove tag '%s': %s\", tag, tostring(err))} end\n return {success=true, data={path=path, tag=tag, removed=true, existed=existed}}\nend\nfunction module.get_tags(params)\n local path = params.path\n if not path or path=='' then return {success=false, error='path is required'} end\n if not PathResolver.isPathAllowed(path) then return {success=false, error='Forbidden path: '..path} end\n local inst = PathResolver.resolve(path)\n if not inst then return {success=false, error='Instance not found: '..path} end\n local ok, tags = pcall(function() return CollectionService:GetTags(inst) end)\n if not ok then return {success=false, error='Failed to get tags: '..tostring(tags)} end\n return {success=true, data={path=path, tags=tags, tagCount=#tags}}\nend\nfunction module.get_tagged(params)\n local tag = params.tag; local rootPath = params.rootPath\n if not tag or tag=='' then return {success=false, error='tag is required'} end\n local rootInst\n if rootPath and rootPath~='' then\n  if not PathResolver.isPathAllowed(rootPath) then return {success=false, error='Forbidden path: '..rootPath} end\n  rootInst = PathResolver.resolve(rootPath)\n  if not rootInst then return {success=false, error='Root not found: '..rootPath} end\n end\n local ok, tagged = pcall(function() return CollectionService:GetTagged(tag) end)\n if not ok then return {success=false, error=string.format(\"Failed to get tagged for '%s': %s\", tag, tostring(tagged))} end\n local filtered = {}\n for _, inst in ipairs(tagged) do\n  if rootInst then if inst:IsDescendantOf(rootInst) or inst==rootInst then table.insert(filtered, inst) end\n  else table.insert(filtered, inst) end\n end\n local serialized = {}\n for _, inst in ipairs(filtered) do table.insert(serialized, Serializer.serializeInstance(inst, false, false)) end\n return {success=true, data={tag=tag, rootPath=rootPath, instances=serialized, instanceCount=#serialized}}\nend\nfunction module.has_tag(params)\n local path = params.path; local tag = params.tag\n if not path or path=='' then return {success=false, error='path is required'} end\n if not tag or tag=='' then return {success=false, error='tag is required'} end\n if not PathResolver.isPathAllowed(path) then return {success=false, error='Forbidden path: '..path} end\n local inst = PathResolver.resolve(path)\n if not inst then return {success=false, error='Instance not found: '..path} end\n local ok, has = pcall(function() return CollectionService:HasTag(inst, tag) end)\n if not ok then return {success=false, error=string.format(\"Failed to check tag '%s': %s\", tag, tostring(has))} end\n return {success=true, data={path=path, tag=tag, hasTag=has}}\nend\nreturn module"

-- SearchHandlers
local sch=core:FindFirstChild("SearchHandlers")
sch.Source="--[[ NovaMCP SearchHandlers ]]\nlocal PathResolver = require(script.Parent.Parent.Parent.Utils.PathResolver)\nlocal InstanceIdentity = require(script.Parent.Parent.Parent.Utils.InstanceIdentity)\nlocal module = {}\nlocal function isForbiddenInstance(inst) return not PathResolver.isPathAllowed(PathResolver.getPath(inst)) end\nlocal function serializeResult(inst) return InstanceIdentity.attach({path=PathResolver.getPath(inst)}, inst) end\nlocal function wildcardToPattern(pattern)\n local esc = pattern:gsub('[%(%)%.%%%+%-%[%]%^%$]', '%%%1')\n esc = esc:gsub('%*', '.*'):gsub('%?', '.')\n return '^'..esc..'$'\nend\nfunction module.search_by_name(params)\n local pattern = params.pattern; local root = params.root or 'game'; local maxResults = params.maxResults or 100; local caseSensitive = params.caseSensitive==nil and false or params.caseSensitive\n if not pattern or pattern=='' then return {success=false, error='Pattern is required'} end\n local rootInst = PathResolver.resolve(root)\n if not rootInst then return {success=false, error='Root not found: '..root} end\n if isForbiddenInstance(rootInst) then return {success=false, error='Access to forbidden path: '..root} end\n local regex = wildcardToPattern(pattern)\n if not caseSensitive then regex = regex:lower() end\n local results = {}\n for _, desc in ipairs(rootInst:GetDescendants()) do\n  if not isForbiddenInstance(desc) then\n   local name = desc.Name\n   if not caseSensitive then name = name:lower() end\n   if name:match(regex) then\n    table.insert(results, serializeResult(desc))\n    if #results >= maxResults then break end\n   end\n  end\n end\n return {success=true, data={results=results, count=#results}}\nend\nfunction module.search_by_class(params)\n local className = params.className; local root = params.root or 'game'; local maxResults = params.maxResults or 100; local includeSubclasses = params.includeSubclasses==nil and true or params.includeSubclasses\n if not className or className=='' then return {success=false, error='className is required'} end\n local rootInst = PathResolver.resolve(root)\n if not rootInst then return {success=false, error='Root not found: '..root} end\n if isForbiddenInstance(rootInst) then return {success=false, error='Access to forbidden path: '..root} end\n local results = {}\n for _, desc in ipairs(rootInst:GetDescendants()) do\n  if not isForbiddenInstance(desc) then\n   local match = false\n   if includeSubclasses then local ok, is = pcall(function() return desc:IsA(className) end); match = ok and is\n   else match = desc.ClassName == className end\n   if match then\n    table.insert(results, serializeResult(desc))\n    if #results >= maxResults then break end\n   end\n  end\n end\n return {success=true, data={results=results, count=#results}}\nend\nreturn module"

-- InstanceTreeHandler
local ith=core:FindFirstChild("InstanceTreeHandler")
ith.Source="--[[ NovaMCP InstanceTreeHandler ]]\nlocal PathResolver = require(script.Parent.Parent.Parent.Utils.PathResolver)\nlocal TypeConverter = require(script.Parent.Parent.Parent.Utils.TypeConverter)\nlocal Serializer = require(script.Parent.Parent.Parent.Utils.Serializer)\nlocal module = {}\nlocal MAX_DEPTH = 20; local MAX_INSTANCES = 500\nlocal function createNode(nodeSpec, parent, depth, counter)\n if depth > MAX_DEPTH then return nil, string.format('Max depth exceeded (%d)', MAX_DEPTH) end\n if counter.created >= MAX_INSTANCES then return nil, string.format('Max instances exceeded (%d)', MAX_INSTANCES) end\n local className = nodeSpec.className\n if not className or className=='' then return nil, 'className is required' end\n local ok, inst = pcall(function() return Instance.new(className) end)\n if not ok then return nil, 'Invalid className: '..className..' - '..tostring(inst) end\n if nodeSpec.name and nodeSpec.name~='' then inst.Name = nodeSpec.name end\n if nodeSpec.properties and type(nodeSpec.properties)=='table' then\n  for prop, val in pairs(nodeSpec.properties) do\n   local ok2, err = pcall(function() inst[prop] = TypeConverter.toRoblox(val) end)\n   if not ok2 then warn(string.format('Failed to set property %s on %s: %s', prop, className, err)) end\n  end\n end\n inst.Parent = parent; counter.created = counter.created + 1\n if nodeSpec.children and type(nodeSpec.children)=='table' then\n  for _, child in ipairs(nodeSpec.children) do\n   if type(child)~='table' then warn('Skipping invalid child'); continue end\n   local childInst, childErr = createNode(child, inst, depth+1, counter)\n   if not childInst then warn(string.format('Failed to create child: %s', tostring(childErr))) end\n  end\n end\n return inst, nil\nend\nfunction module.create_instance_tree(params)\n local parent = params.parent; local tree = params.tree\n if not parent or parent=='' then return {success=false, error='parent is required'} end\n if not tree or type(tree)~='table' then return {success=false, error='tree is required'} end\n if not PathResolver.isPathAllowed(parent) then return {success=false, error='Forbidden parent path: '..parent} end\n local parentInst = PathResolver.resolve(parent)\n if not parentInst then return {success=false, error='Parent not found: '..parent} end\n local counter = {created=0}\n local root, err = createNode(tree, parentInst, 1, counter)\n if not root then return {success=false, error='Failed to create tree: '..tostring(err)} end\n local serialized = Serializer.serializeInstance(root, true, true)\n return {success=true, data={created=counter.created, rootPath=PathResolver.getPath(root), rootClassName=root.ClassName, rootName=root.Name, tree=serialized}}\nend\nreturn module"

-- SyncControl
local sync=core:FindFirstChild("SyncControl")
sync.Source="--[[ NovaMCP SyncControl ]]\nlocal SyncConfig = require(script.Parent.Parent.Parent.Sync.SyncConfig)\nlocal module = {}\nlocal syncManager\nlocal function getStartOptions(opts)\n if not opts then return nil end\n local preserve = opts.preserveLocalFiles\n if type(preserve)~='table' or #preserve==0 then return nil end\n return {preserveLocalFiles=preserve}\nend\nfunction module.setSyncManager(mgr) syncManager = mgr end\nfunction module.start_sync(params)\n if not syncManager then return {success=false, error='SyncManager not initialized'} end\n if not syncManager:isMcpConnected() then return {success=false, error='MCP server not connected'} end\n local state = syncManager:getState()\n if state=='syncing' or state=='initializing' then return {success=true, data={state=state, message='Sync already active'}} end\n syncManager:startSync(getStartOptions(params))\n return {success=true, data={state=syncManager:getState(), message='Sync started'}}\nend\nfunction module.stop_sync(params)\n if not syncManager then return {success=false, error='SyncManager not initialized'} end\n local prev = syncManager:getState()\n syncManager:stopSync()\n return {success=true, data={previousState=prev, state=syncManager:getState(), message=prev=='idle' and 'Sync already idle' or 'Sync stopped'}}\nend\nfunction module.get_state(params)\n if not syncManager then return {success=false, error='SyncManager not initialized'} end\n local types = {'scripts','values','containers','data','services'}\n local directions = {}; local modes = {}\n for _, t in ipairs(types) do directions[t]=SyncConfig.getSyncDirectionForType(t); modes[t]=SyncConfig.getApplyModeForType(t) end\n return {success=true, data={state=syncManager:getState(), syncMode=syncManager:getSyncMode(), mcpConnected=syncManager:isMcpConnected(), instanceCount=syncManager:getInstanceCount(), scriptCount=syncManager:getScriptCount(), syncRoot=syncManager:getSyncRoot(), directions=directions, applyModes=modes, reverseSyncMode=SyncConfig.getReverseSyncMode(), hasAnyReverseSync=SyncConfig.hasAnyReverseSync()}}\nend\nreturn module"

-- LogHandlers
local lh=core:FindFirstChild("LogHandlers")
lh.Source="--[[ NovaMCP LogHandlers ]]\nlocal LogService = game:GetService('LogService')\nlocal module = {}\nlocal MAX_BUFFER = 500; local buffer = {}; local seq = 0; local capturing = false\nlocal TYPE_MAP = {[Enum.MessageType.MessageOutput]='info', [Enum.MessageType.MessageWarning]='warning', [Enum.MessageType.MessageError]='error', [Enum.MessageType.MessageInfo]='info'}\nlocal VALID_TYPES = {info=true, warning=true, error=true}\nlocal function appendEntry(msg, msgType, timestampMs)\n seq = seq + 1\n local ts = type(timestampMs)=='number' and timestampMs or DateTime.now().UnixTimestampMillis\n local entry = {message=tostring(msg), type=VALID_TYPES[msgType] and msgType or 'info', timestamp=type(timestampMs)=='number' and math.floor(timestampMs/1000) or os.time(), timestampMs=ts, seq=seq}\n table.insert(buffer, entry)\n if #buffer > MAX_BUFFER then table.remove(buffer, 1) end\n return entry\nend\nlocal function getBufferBounds()\n local last = seq; local oldest = seq + 1\n if #buffer > 0 then oldest = buffer[1].seq end\n return last, oldest\nend\nlocal function matchesFilters(entry, filterType, since, pattern)\n if filterType~='all' and entry.type~=filterType then return false end\n if since and entry.timestampMs < since then return false end\n if pattern and string.find(entry.message, pattern, 1, true)==nil then return false end\n return true\nend\nlocal CURSOR = {OK='ok', GAP='gap', RESET='reset'}\nlocal function getCursorStatus(cursor, lastSeq, oldestSeq)\n if cursor > lastSeq then return CURSOR.RESET end\n if cursor < (oldestSeq - 1) then return CURSOR.GAP end\n return CURSOR.OK\nend\nlocal function startCapturing()\n if capturing then return end\n capturing = true\n LogService.MessageOut:Connect(function(msg, msgType) appendEntry(msg, TYPE_MAP[msgType]) end)\n print('[LogHandlers] Started log capture')\nend\nstartCapturing()\nfunction module.append_external_log(log)\n if type(log)~='table' or type(log.message)~='string' then return end\n appendEntry(log.message, log.type, log.timestampMs)\nend\nfunction module.get_output_logs(params)\n local ok, result = pcall(function()\n  local filterType = params.type or 'all'; local limit = params.limit or 100; local since = params.since; local sinceSeq = params.sinceSeq; local pattern = params.pattern\n  local lastSeq, oldestSeq = getBufferBounds()\n  if limit > 500 then limit = 500 end\n  if sinceSeq == nil then\n   local results = {}\n   for i = #buffer, 1, -1 do\n    if matchesFilters(buffer[i], filterType, since, pattern) then\n     table.insert(results, {message=buffer[i].message, type=buffer[i].type, timestamp=buffer[i].timestamp, timestampMs=buffer[i].timestampMs, seq=buffer[i].seq})\n     if #results >= limit then break end\n    end\n   end\n   for i = 1, math.floor(#results/2) do results[i], results[#results-i+1] = results[#results-i+1], results[i] end\n   return {logs=results, count=#results, totalBuffered=#buffer, lastSeq=lastSeq, oldestSeq=oldestSeq}\n  end\n  local cursorStatus = getCursorStatus(sinceSeq, lastSeq, oldestSeq)\n  local cursor = sinceSeq; local hasMore = false; local items = {}\n  if cursorStatus == CURSOR.GAP or cursorStatus == CURSOR.RESET then cursor = oldestSeq - 1 end\n  for _, entry in ipairs(buffer) do\n   if entry.seq <= cursor then continue end\n   if not matchesFilters(entry, filterType, since, pattern) then continue end\n   if #items >= limit then hasMore = true; break end\n   table.insert(items, {message=entry.message, type=entry.type, timestamp=entry.timestamp, timestampMs=entry.timestampMs, seq=entry.seq})\n  end\n  return {logs=items, count=#items, totalBuffered=#buffer, lastSeq=lastSeq, oldestSeq=oldestSeq, hasMore=hasMore, cursorStatus=cursorStatus}\n end)\n if ok then return {success=true, data=result} else return {success=false, error=tostring(result)} end\nend\nfunction module.clear_output_logs(params)\n local ok, result = pcall(function()\n  local cleared = #buffer; buffer = {}; local last, oldest = getBufferBounds()\n  return {cleared=true, clearedCount=cleared, lastSeq=last, oldestSeq=oldest}\n end)\n if ok then return {success=true, data=result} else return {success=false, error=tostring(result)} end\nend\nfunction module.get_recent_errors(params)\n local ok, result = pcall(function()\n  local limit = params.limit or 20; if limit > 100 then limit = 100 end\n  local last, oldest = getBufferBounds()\n  local errors = {}\n  for i = #buffer, 1, -1 do\n   if buffer[i].type == 'error' then\n    table.insert(errors, {message=buffer[i].message, type=buffer[i].type, timestamp=buffer[i].timestamp, timestampMs=buffer[i].timestampMs, seq=buffer[i].seq})\n    if #errors >= limit then break end\n   end\n  end\n  for i = 1, math.floor(#errors/2) do errors[i], errors[#errors-i+1] = errors[#errors-i+1], errors[i] end\n  return {errors=errors, count=#errors, hasErrors=#errors>0, lastSeq=last, oldestSeq=oldest}\n end)\n if ok then return {success=true, data=result} else return {success=false, error=tostring(result)} end\nend\nreturn module"

return "Core handlers batch done: Selection, Tag, Search, InstanceTree, SyncControl, LogHandlers"
